#include <stdio.h>
#include <string.h>

void helper(int left, int right, char *str) {
        if (left >= right)
            return ;

        char temp = str[right];
        str[right] = str[left];
        str[left] = temp;

        helper(left + 1, right - 1, str);
}


void reverseString(char* s, int sSize) {
    helper(0, sSize - 1, s);   
}



int main()
{
    char str[] = "\
        \
        \
        \
        \
        \
        \
        \
        \
        \
        \
        \
        \
        \
        \
        \
        \
        \
        \
        \
        \
        \
        \
        ";
    reverseString(str, strlen(str));
    printf("%s", str);


    return 0;
}